mapper.select:
SELECT 



ORDER BY ${sortColumn} ${sortDirection}, t.take_seq DESC

    LIMIT #{size} OFFSET #{offset}

mapper.insert:
INSERT INTO tb_stocktake_line (take_seq, location_seq, sku_seq, supplier_seq, stock_seq, qty_book) SELECT #{takeSeq}, s.location_seq, s.sku_seq, s.supplier_seq, s.stock_seq, s.qty_on_hand FROM tb_stock s JOIN tb_location l ON l.location_seq = s.location_seq JOIN tb_sku k ON k.sku_seq = s.sku_seq JOIN tb_product pr ON pr.product_seq = k.product_seq WHERE l.warehouse_seq = #{warehouseSeq} AND l.use_yn = 'Y'
AND l.zone_code = #{zoneCode}
AND (k.sku_id ILIKE '%' || #{skuKeyword} || '%' OR pr.product_name ILIKE '%' || #{skuKeyword} || '%')

mapper.select:
SELECT COUNT(*) FROM tb_stock s JOIN tb_location l ON l.location_seq = s.location_seq JOIN tb_sku k ON k.sku_seq = s.sku_seq JOIN tb_product pr ON pr.product_seq = k.product_seq WHERE l.warehouse_seq = #{warehouseSeq} AND l.use_yn = 'Y'
AND l.zone_code = #{zoneCode}
AND (k.sku_id ILIKE '%' || #{skuKeyword} || '%' OR pr.product_name ILIKE '%' || #{skuKeyword} || '%')

mapper.insert:
INSERT INTO tb_stocktake_line (take_seq, location_seq, sku_seq, supplier_seq, stock_seq, qty_book) SELECT #{takeSeq}, s.location_seq, s.sku_seq, s.supplier_seq, s.stock_seq, s.qty_on_hand FROM tb_stock s JOIN tb_location l ON l.location_seq = s.location_seq WHERE l.warehouse_seq = #{warehouseSeq} AND s.stock_seq IN
#{seq}
AND NOT EXISTS ( SELECT 1 FROM tb_stocktake_line x WHERE x.take_seq = #{takeSeq} AND x.location_seq = s.location_seq AND x.sku_seq = s.sku_seq AND (x.supplier_seq = s.supplier_seq OR (x.supplier_seq IS NULL AND s.supplier_seq IS NULL)))

mapper.select:
SELECT COUNT(*) FROM tb_stocktake_line
 WHERE take_seq = #{takeSeq}
   AND location_seq = #{locationSeq}
   AND sku_seq = #{skuSeq}

SELECT line_seq FROM tb_stocktake_line
 WHERE take_seq = #{takeSeq}
   AND location_seq = #{locationSeq}
   AND sku_seq = #{skuSeq}

mapper.update:
UPDATE tb_stocktake_line
   SET applied_history_seq = #{historySeq}
 WHERE line_seq = #{lineSeq}
